                    Surface aliasA(backend,shared),aliasB(backend,shared);
                    assert(aliasA.surfaceBinding()==aliasB.surfaceBinding());
                    targets={&aliasA,&aliasB};assert(prepare()==5);
                    // Distinct source/history objects with the same binding
