            fixtureResource.fill(0);
            assert(tglWithOwnedFfdiPreparation(owner,0x19,1,{},{},
                [](const auto&,const auto&,const auto&) noexcept {assert(false);return 0;})==5);
            const std::array reverseRoles{&destination,&owner,&destination};
