static void testActualNv12LayoutSnapshot() {
    TglOwnedNv12Layout layout;
    constexpr uintptr_t base=0x10000;
    assert(tglCaptureOwnedNv12Layout(layout,base,4096,{base+128,base+2176},
                                     64,32,{64,64},{32,16}));
    assert(layout.offset[0]==128 && layout.offset[1]==2176 && layout.pitch[0]==64);
    for(unsigned bad=0;bad<6;++bad) {
        auto planes=std::array<uintptr_t,2>{base+128,base+2176};
        auto pitch=std::array<size_t,2>{64,64};size_t capacity=4096,width=64;
        if(bad==0) planes[1]=base+127;
        if(bad==1) planes[1]=base+2048;
        if(bad==2) pitch[1]=0;
        if(bad==3) capacity=3000;
        if(bad==4) width=63;
        if(bad==5) planes[0]=base-1;
        assert(!tglCaptureOwnedNv12Layout(layout,base,capacity,planes,width,32,pitch,{32,16}));
        assert(layout.offset[0]==128 && layout.offset[1]==2176);
    }
    struct Api {
        unsigned mode=0,locks=0,unlocks=0,retains=0,releases=0;
        bool* lease=nullptr;
        bool complete=false,unequalPitch=false;
        uintptr_t surface(uintptr_t h) noexcept {return h;}
        bool retain(uintptr_t) noexcept {++retains;return mode!=4;}
        void release(uintptr_t) noexcept {++releases;}
        int lock(uintptr_t) noexcept {++locks;return mode==1?31:0;}
        int unlock(uintptr_t) noexcept {++unlocks;return mode==3?17:0;}
        bool readLayout(uintptr_t,TglOwnedNv12Layout& out) noexcept {
            if(lease) *lease=false;
            if(mode==2) return false;
            if(complete) return tglCaptureOwnedNv12Layout(out,0x10000,8192,
                {0x10080,0x10880},64,32,{64,unequalPitch?128u:64u},{32,16});
            out.width=960;return true;
        }
    };
    struct Sink {
        bool deny=false;unsigned reservations=0,cancels=0,commits=0;
        bool reserve(uintptr_t) noexcept {++reservations;return !deny;}
        void cancel() noexcept {++cancels;}
        void commit(uintptr_t) noexcept {++commits;}
    };
    std::array<uint8_t,0x148> resource{};
    uint32_t type=1,format=0x19;uintptr_t handle=1;
    std::memcpy(resource.data()+0x14,&type,4);std::memcpy(resource.data()+0x18,&format,4);
    std::memcpy(resource.data()+0x58,&handle,8);
    const uint32_t planeCount=2;std::memcpy(resource.data()+0x60,&planeCount,4);
    for(unsigned mode=0;mode<6;++mode) {
        Api api;api.mode=mode;Sink sink;sink.deny=mode==5;
        TglOwnedNv12Layout out;out.width=77;
        const auto result=tglReadRetainedOwnedNv12Layout(resource,api,sink,out);
        assert(result.ready()==(mode==0) && out.width==(mode==0?960u:77u));
        assert(result.requiresQuarantine()==(mode==3));
        assert(sink.commits==(mode==3?1u:0u));
        assert(api.releases==((mode==4 || mode==5 || mode==3)?0u:1u));
        assert(api.locks==((mode==4 || mode==5)?0u:1u));
        assert(api.unlocks==((mode==1 || mode==4 || mode==5)?0u:1u));
    }
    TglOwnedSurfaceStorage surface;surface.resource=resource;
    struct Owner {
        const TglOwnedSurfaceStorage* original;bool leased=true;
        bool hasSurfaceLease(const TglOwnedSurfaceStorage& s) noexcept {
            return leased && &s==original;
        }
    } owner{&surface};
    Api api;Sink sink;TglOwnedNv12Layout out;out.width=77;
    TglOwnedSurfaceStorage foreign=surface;
    assert(!tglReadLeasedOwnedNv12Layout(owner,foreign,api,sink,out).ready());
    assert(!api.locks && out.width==77);
    api.lease=&owner.leased;
    assert(!tglReadLeasedOwnedNv12Layout(owner,surface,api,sink,out).ready());
    assert(api.unlocks==1 && api.releases==1 && out.width==77);
    owner.leased=true;api.lease=nullptr;
    assert(tglReadLeasedOwnedNv12Layout(owner,surface,api,sink,out).ready());
    assert(out.width==960);
    uint32_t shellFormat=0x19,width=64,height=32;
    std::memcpy(surface.prefix.data()+0x130,&shellFormat,4);
    std::memcpy(surface.prefix.data()+0xd8,&width,4);
    std::memcpy(surface.prefix.data()+0xdc,&height,4);
    const auto originalResource=surface.resource;
    const auto originalPrefix=surface.prefix;
    api.complete=true;api.unequalPitch=true;
    assert(!tglPrepareLeasedOwnedNv12Metadata(owner,surface,api,sink).ready());
    assert(surface.prefix==originalPrefix && surface.resource==originalResource);
    api.unequalPitch=false;
    assert(tglPrepareLeasedOwnedNv12Metadata(owner,surface,api,sink).ready());
    uint32_t pitch=0,y=1,uv=0;
    std::memcpy(&pitch,surface.prefix.data()+0xe0,4);
    std::memcpy(&y,surface.prefix.data()+0xf0,4);
    std::memcpy(&uv,surface.prefix.data()+0x100,4);
    assert(pitch==64 && y==0 && uv==2048 && surface.resource==originalResource);
    const auto descriptor=tglOwnedSfcOutputDescriptor(surface);
    uint32_t uvRow=0;std::memcpy(&uvRow,descriptor.data()+0x24,4);
    assert(uvRow==32);
}
